import * as T from '../vendor/three.module.js';
import {mergeGeometries} from '../vendor/addons/utils/BufferGeometryUtils.js';
export function seeded(seed=7123){let s=seed>>>0;return()=>{s=(Math.imul(s,1664525)+1013904223)>>>0;return s/4294967296;};}
export function mesh(parent,geometry,material,x=0,y=0,z=0){const m=new T.Mesh(geometry,material);m.position.set(x,y,z);m.castShadow=m.receiveShadow=true;parent.add(m);return m;}
export function box(parent,mat,w,h,d,x=0,y=0,z=0){return mesh(parent,new T.BoxGeometry(w,h,d),mat,x,y,z);}
export function tube(parent,mat,points,r=.025,segments=40){const curve=new T.CatmullRomCurve3(points.map(p=>new T.Vector3(...p)));return mesh(parent,new T.TubeGeometry(curve,segments,r,6,false),mat);}
export function cylinderBetween(parent,mat,start,end,r=.04,segments=10){const a=new T.Vector3(...start),b=new T.Vector3(...end),delta=b.clone().sub(a);const o=mesh(parent,new T.CylinderGeometry(r,r,delta.length(),segments),mat);o.position.copy(a).add(b).multiplyScalar(.5);o.quaternion.setFromUnitVectors(new T.Vector3(0,1,0),delta.normalize());return o;}
/** Merge static meshes by material, in root-local coordinates. Animated parts stay outside this group. */
export function batchStatic(root){root.updateMatrixWorld(true);const inverse=root.matrixWorld.clone().invert(),buckets=new Map(),original=new Set();root.traverse(o=>{if(!o.isMesh||o.isInstancedMesh||Array.isArray(o.material))return;const geo=o.geometry.index?o.geometry.toNonIndexed():o.geometry.clone();geo.applyMatrix4(new T.Matrix4().multiplyMatrices(inverse,o.matrixWorld));for(const key of Object.keys(geo.attributes))if(!['position','normal','uv'].includes(key))geo.deleteAttribute(key);if(!geo.attributes.normal)geo.computeVertexNormals();if(!geo.attributes.uv)geo.setAttribute('uv',new T.BufferAttribute(new Float32Array(geo.attributes.position.count*2),2));if(!buckets.has(o.material))buckets.set(o.material,[]);buckets.get(o.material).push(geo);original.add(o.geometry);});root.clear();for(const [mat,geos] of buckets){const combined=mergeGeometries(geos,false);combined.computeBoundingSphere();mesh(root,combined,mat);for(const g of geos)g.dispose();}for(const g of original)g.dispose();return root;}
export class Materials {
 constructor({textures=true,anisotropy=4}={}){this.materials=new Map();this.textures=new Map();this.enabled=textures&&typeof document!=='undefined';this.anisotropy=anisotropy;this.loader=this.enabled?new T.TextureLoader():null;this.disposed=false;this.errors=[];}
 map(set,kind){const key=set+'/'+kind;if(this.textures.has(key))return this.textures.get(key);if(!this.loader)return null;const ext=kind==='normal'?'png':'jpg',url=new URL('../assets/materials/'+set+'/'+kind+'.'+ext,import.meta.url).href;
 const tex=this.loader.load(url,()=>{if(this.disposed)tex.dispose();},undefined,()=>{this.errors.push(url);console.warn('Material texture unavailable:',set,kind);});tex.wrapS=tex.wrapT=T.RepeatWrapping;tex.colorSpace=kind==='color'?T.SRGBColorSpace:T.NoColorSpace;tex.anisotropy=this.anisotropy;this.textures.set(key,tex);return tex;}
 get(name,color=0xffffff,options={}){if(this.materials.has(name))return this.materials.get(name);const {texture:set,...parameters}=options,mat=new T.MeshStandardMaterial({color,roughness:.82,...parameters});if(set&&this.enabled){mat.map=this.map(set,'color');mat.normalMap=this.map(set,'normal');mat.roughnessMap=this.map(set,'roughness');mat.normalScale.set(.65,.65);}mat.name=name;mat.userData.textureSet=set||null;this.materials.set(name,mat);return mat;}
 quality(q){const a=q==='Baixa'?1:q==='Alta'?8:4;for(const t of this.textures.values())t.anisotropy=Math.min(a,this.anisotropy);}
 dispose(){if(this.disposed)return;this.disposed=true;for(const t of this.textures.values())t.dispose();for(const m of this.materials.values())m.dispose();this.textures.clear();this.materials.clear();}
}
